suppressPackageStartupMessages({library(ORFik);library(data.table);library(GenomicRanges);library(rtracklayer)})
setDTthreads(1);df<-read.experiment('all_merged-Homo_sapiens',validate=FALSE);tx<-loadRegion(df,'mrna');reads<-ORFik::filepath(df,'bigwig',suffix_stem=c('_pshifted',''))[[1]]
candidate<-function(gr,gap=500L){ ex<-gr[[1]]; merged<-reduce(ex,ignore.strand=TRUE,min.gapwidth=gap+1L);strand(merged)<-'*'; st<-as.character(strand(ex)[1]); idxfile<-if(st=='+')1L else 2L; v<-rtracklayer::import.bw(reads[[idxfile]],which=merged,as='NumericList'); vals<-unlist(v,use.names=FALSE); ix<-findInterval(start(ex),start(merged));off<-c(0,head(cumsum(width(merged)),-1L))[ix]+start(ex)-start(merged)[ix]+1L; counts<-vals[sequence(width(ex),from=off+if(st=='-')width(ex)-1L else 0L,by=if(st=='-')-1L else 1L)];if(all(round(counts)==counts))counts<-as.integer(counts); dt<-data.table(count=counts,genes=rep.int(1L,length(counts)),position=seq_along(counts));dt[,frame:=(position-1)%%3];dt}
# Choose TTN and a high-exon plus-strand transcript. Prototype is for these
# two-strand, known-chromosome examples only; it is not a production reader.
orderids<-names(sort(lengths(tx),decreasing=TRUE)); selected<-c('ENST00000589042');for(id in head(orderids,500)){sg<-as.character(strand(tx[[id]])[1]); if(sg=='+' && !any(vapply(selected,function(x)as.character(strand(tx[[x]])[1])=='+',logical(1))))selected<-c(selected,id);if(length(selected)==2)break}
for(id in selected){gr<-tx[id];base<-function()ORFik::coveragePerTiling(gr,reads,as.data.table=TRUE,withFrames=TRUE,is.sorted=TRUE);fast<-function()candidate(gr);b<-base();f<-fast();stopifnot(isTRUE(all.equal(b,f,tolerance=0,check.attributes=TRUE)));cat('TRANSCRIPT',id,'strand',as.character(strand(gr[[1]])[1]),'exons',length(gr[[1]]),'nt',nrow(b),'identical cols',all(vapply(names(b),function(x)identical(b[[x]],f[[x]]),logical(1))),'\n');for(i in 1:6){ if(i%%2){st<-proc.time()[['elapsed']];base();tb<-proc.time()[['elapsed']]-st;st<-proc.time()[['elapsed']];fast();tf<-proc.time()[['elapsed']]-st}else{st<-proc.time()[['elapsed']];fast();tf<-proc.time()[['elapsed']]-st;st<-proc.time()[['elapsed']];base();tb<-proc.time()[['elapsed']]-st};cat('round',i,'baseline',tb,'candidate',tf,'\n')}}
